//! Lane 1 — the mandatory `unreadable` contract.
//!
//! No root required. On a real host, pid 1's fd table is always forbidden to a
//! normal-uid reader (`EACCES` on linux `/proc/1/fd`, `EPERM` on darwin
//! libproc for launchd). Inside the nix sandbox pid 1 is the builder's own
//! init as the same uid, so that path is readable — the vanished-pid case
//! still pins the U-row contract there.

mod common;

use common::{osfacts, parse_tsv};

#[test]
fn pid_one_ports_yields_u_row() {
    #[cfg(target_os = "linux")]
    {
        // Precondition: /proc/1/fd must actually be denied. The nix sandbox's
        // pid 1 is a same-uid bash, so readdir succeeds and the fixture does
        // not apply — vanished_pid_yields_u_row covers the U-row contract.
        if std::fs::read_dir("/proc/1/fd").is_ok() {
            eprintln!(
                "note: /proc/1/fd is readable (nix sandbox topology); \
                 pid-1 EACCES fixture N/A — see vanished_pid_yields_u_row"
            );
            return;
        }
    }

    let out = osfacts()
        .args(["snapshot", "--pids", "1", "--procs", "--ports"])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let stdout = String::from_utf8(out).unwrap();
    let (v, _procs, _ports, unreadable, _errors) = parse_tsv(&stdout);
    assert_eq!(v, 2);
    assert!(
        unreadable.iter().any(|u| {
            u.starts_with("U\t1\tports\t")
                && (u.contains("EACCES") || u.contains("EPERM") || u.contains("ESRCH"))
        }),
        "expected a U row for pid 1 with a permission errno; unreadable={unreadable:?}\nfull:\n{stdout}"
    );
}

#[test]
fn vanished_pid_yields_u_row() {
    let gone = 2_147_483_646u32;
    let out = osfacts()
        .args([
            "snapshot",
            "--pids",
            &gone.to_string(),
            "--procs",
            "--ports",
            "--cpu-time",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let stdout = String::from_utf8(out).unwrap();
    let (v, procs, _, unreadable, _errors) = parse_tsv(&stdout);
    assert_eq!(v, 2);
    assert!(
        procs
            .iter()
            .all(|p| !p.starts_with(&format!("P\t{gone}\t"))),
        "must not invent a P row for a vanished pid"
    );
    assert!(
        unreadable
            .iter()
            .any(|u| u.starts_with(&format!("U\t{gone}\tcpu_time\t"))),
        "expected a cpu_time U row for pid {gone}; unreadable={unreadable:?}"
    );
}

import { defineConfig } from "vitest/config";

export default defineConfig({
  test: {
    include: ["src/**/*.test.ts"],
  },
});

//! Unit tests for the vendored darwin `insi_vflag` address-slot decode.
//! Fixtures run on every host — the dual-stack flag-ordering bug is in the
//! *decode*, and the scar tissue travels with the code.

use osfacts::{slot_from_vflag, AddressSlot, AF_INET, AF_INET6, INI_IPV4, INI_IPV6};

#[test]
fn af_inet_is_always_v4() {
    assert_eq!(slot_from_vflag(AF_INET, 0), AddressSlot::V4);
    assert_eq!(slot_from_vflag(AF_INET, INI_IPV4), AddressSlot::V4);
    assert_eq!(
        slot_from_vflag(AF_INET, INI_IPV4 | INI_IPV6),
        AddressSlot::V4
    );
}

#[test]
fn dual_stack_wildcard_checks_ipv6_first() {
    let vflag = INI_IPV4 | INI_IPV6;
    assert_eq!(
        slot_from_vflag(AF_INET6, vflag),
        AddressSlot::V6,
        "dual-stack :: must take the v6 slot, not the v4 wildcard"
    );
}

#[test]
fn v4_mapped_uses_v4_slot() {
    assert_eq!(
        slot_from_vflag(AF_INET6, INI_IPV4),
        AddressSlot::V4,
        "v4-mapped must read the 4-byte slot"
    );
}

#[test]
fn genuine_v6_loopback() {
    assert_eq!(slot_from_vflag(AF_INET6, INI_IPV6), AddressSlot::V6);
}

#[test]
fn neither_flag_falls_back_to_family() {
    assert_eq!(slot_from_vflag(AF_INET6, 0), AddressSlot::V6);
}

//! Lane 1 — proptest, pure functions only.
//!
//! (a) address-decode round-trips (PR-#57 bug class: v4-mapped, dual-stack
//!     both-flags via the slot decision; network-hex and /proc-hex codecs).
//! (b) TSV name sanitizing never yields an unescaped delimiter.

use osfacts::{
    decode_network_hex, decode_proc_hex, encode_hex, encode_proc_hex, encode_tsv_string,
    encode_tsv_strings, sanitize_name, slot_from_vflag, AddressSlot, AF_INET, AF_INET6, INI_IPV4,
    INI_IPV6,
};
use proptest::prelude::*;

fn arbitrary_string() -> impl Strategy<Value = String> {
    prop::collection::vec(any::<char>(), 0..128)
        .prop_map(|characters| characters.into_iter().collect())
}

// ── (a) address decode ──────────────────────────────────────────────────

proptest! {
    /// Network-order hex is its own inverse for v4 (4 bytes) and v6 (16 bytes).
    #[test]
    fn network_hex_roundtrip(bytes in prop::collection::vec(any::<u8>(), 4)) {
        let hex = encode_hex(&bytes);
        let back = decode_network_hex(&hex).expect("decode");
        prop_assert_eq!(bytes, back);
    }

    #[test]
    fn network_hex_roundtrip_v6(bytes in prop::collection::vec(any::<u8>(), 16)) {
        let hex = encode_hex(&bytes);
        let back = decode_network_hex(&hex).expect("decode");
        prop_assert_eq!(bytes, back);
    }

    /// `/proc` host-order hex round-trips through the word-swap codec.
    #[test]
    fn proc_hex_roundtrip_v4(bytes in prop::collection::vec(any::<u8>(), 4)) {
        let hex = encode_proc_hex(&bytes).expect("encode");
        let back = decode_proc_hex(&hex).expect("decode");
        prop_assert_eq!(bytes, back);
    }

    #[test]
    fn proc_hex_roundtrip_v6(bytes in prop::collection::vec(any::<u8>(), 16)) {
        let hex = encode_proc_hex(&bytes).expect("encode");
        let back = decode_proc_hex(&hex).expect("decode");
        prop_assert_eq!(bytes, back);
    }
}

#[test]
fn dual_stack_both_flags_is_v6_slot() {
    // The scar: vflag = 0x03 must NOT collapse to the v4 wildcard.
    assert_eq!(
        slot_from_vflag(AF_INET6, INI_IPV4 | INI_IPV6),
        AddressSlot::V6
    );
}

#[test]
fn v4_mapped_flag_is_v4_slot() {
    assert_eq!(slot_from_vflag(AF_INET6, INI_IPV4), AddressSlot::V4);
}

#[test]
fn af_inet_always_v4_slot() {
    assert_eq!(slot_from_vflag(AF_INET, 0), AddressSlot::V4);
    assert_eq!(
        slot_from_vflag(AF_INET, INI_IPV4 | INI_IPV6),
        AddressSlot::V4
    );
}

// ── (b) TSV escaping ────────────────────────────────────────────────────

proptest! {
    /// sanitize_name never emits a TSV delimiter or a line break, so a name
    /// used as the last P-field cannot shift the field count.
    #[test]
    fn sanitize_name_never_emits_delimiters(name in ".*") {
        let s = sanitize_name(&name);
        prop_assert!(!s.contains('\t'), "tab survived: {s:?}");
        prop_assert!(!s.contains('\n'), "newline survived: {s:?}");
        prop_assert!(!s.contains('\r'), "cr survived: {s:?}");
    }

    /// A P-row built with a hostile name always has exactly 4 fields.
    #[test]
    fn p_row_arity_under_hostile_names(name in ".*") {
        let s = sanitize_name(&name);
        let row = format!("P\t1\t0\t{s}");
        // split on tab — exactly 4 fields (tag, pid, ppid, name).
        let fields: Vec<&str> = row.split('\t').collect();
        prop_assert_eq!(fields.len(), 4);
        prop_assert_eq!(fields[0], "P");
    }


    #[test]
    fn cwd_json_field_roundtrips_hostile_text(value in arbitrary_string()) {
        let encoded = encode_tsv_string(&value);
        let row = format!("CWD\t1\t{encoded}");
        let fields: Vec<&str> = row.split('\t').collect();
        prop_assert_eq!(fields.len(), 3);
        let decoded: String = serde_json::from_str(fields[2]).expect("decode cwd");
        prop_assert_eq!(decoded, value);
    }

    #[test]
    fn argv_json_field_roundtrips_hostile_text(values in prop::collection::vec(arbitrary_string(), 0..20)) {
        let encoded = encode_tsv_strings(&values);
        let row = format!("ARGV\t1\t{encoded}");
        let fields: Vec<&str> = row.split('\t').collect();
        prop_assert_eq!(fields.len(), 3);
        let decoded: Vec<String> = serde_json::from_str(fields[2]).expect("decode argv");
        prop_assert_eq!(decoded, values);
    }
}

//! OSF3 + OSF6 + OSF7 contract pins. These are self-referential fixtures:
//! they assert facts about processes/sockets created by this test, never host
//! inventory accidents.

mod common;

use common::{osfacts, Listener};
use osfacts::Facet;
use std::thread;
use std::time::Duration;

/// `facets.json` is the ONE declaration of the V2 facet vocabulary that both
/// languages can hold. Rust owns it (the `Facet` enum below is its source);
/// this test pins the checked-in file to the enum, and
/// `client-ts/src/facets.test.ts` pins the TypeScript unions to the same file.
/// Adding a facet on one side without the other therefore fails CI in the fast
/// unit lane, instead of surfacing as a consumer parse error at runtime.
#[test]
fn facets_json_is_the_enum() {
    let body = include_str!("../facets.json");
    let file: serde_json::Value = serde_json::from_str(body).expect("facets.json is JSON");
    let names = |facets: &[Facet]| -> Vec<String> {
        facets.iter().map(|f| f.as_str().to_owned()).collect()
    };
    let listed = |key: &str| -> Vec<String> {
        file[key]
            .as_array()
            .unwrap_or_else(|| panic!("facets.json is missing '{key}'"))
            .iter()
            .map(|v| v.as_str().expect("facet names are strings").to_owned())
            .collect()
    };
    assert_eq!(listed("unreadable"), names(Facet::UNREADABLE));
    assert_eq!(listed("snapshotSource"), names(Facet::SNAPSHOT_SOURCE));
    assert_eq!(
        listed("socketHoldersSource"),
        names(Facet::SOCKET_HOLDERS_SOURCE)
    );
    assert_eq!(listed("hostSource"), names(Facet::HOST_SOURCE));
}

/// Each verb owns its own `E` vocabulary, so a consumer cannot match a facet
/// name across verbs by accident. `socket_holders` is the one facet only the
/// third verb can name — and it is the ONLY one that verb can name: its
/// `--procs` failures are per-pid `U` rows, so an `E … proc …` row on this
/// verb is a shape nothing writes and the projection must not promise it.
#[test]
fn each_verb_owns_its_source_facet_vocabulary() {
    assert!(Facet::SOCKET_HOLDERS_SOURCE.contains(&Facet::SocketHolders));
    assert!(!Facet::SNAPSHOT_SOURCE.contains(&Facet::SocketHolders));
    assert!(!Facet::HOST_SOURCE.contains(&Facet::SocketHolders));
    assert_eq!(Facet::SOCKET_HOLDERS_SOURCE, &[Facet::SocketHolders]);
    assert!(Facet::UNREADABLE.contains(&Facet::Proc));
}

/// The one darwin source that feeds four facets must name the facet the ASK
/// actually loses, not just `proc` — otherwise a `--uid` consumer scoping
/// blindness by facet reads an empty `uids` array as "no process has a uid".
/// Linux has no equivalent single-source-many-facets shape; this pins the
/// vocabulary side of the contract on both.
#[test]
fn a_uid_only_ask_can_report_uid_blindness() {
    assert!(Facet::SNAPSHOT_SOURCE.contains(&Facet::Uid));
    assert!(Facet::SNAPSHOT_SOURCE.contains(&Facet::Status));
    assert!(Facet::SNAPSHOT_SOURCE.contains(&Facet::StartTime));
}

fn rows(stdout: &str, tag: &str) -> Vec<Vec<String>> {
    stdout
        .lines()
        .filter_map(|line| {
            let fields: Vec<String> = line.split('\t').map(str::to_owned).collect();
            (fields.first().is_some_and(|field| field == tag)).then_some(fields)
        })
        .collect()
}

fn snapshot_self(facet: &str) -> String {
    let pid = std::process::id();
    let out = osfacts()
        .args(["snapshot", "--pids", &pid.to_string(), facet])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    String::from_utf8(out).expect("utf8")
}

#[test]
fn uid_facet_reports_real_uid() {
    let stdout = snapshot_self("--uid");
    let uid = rows(&stdout, "UID");
    assert_eq!(uid.len(), 1, "{stdout}");
    assert_eq!(uid[0][1], std::process::id().to_string());
    assert_eq!(uid[0][2], unsafe { libc::getuid() }.to_string());
}

#[test]
fn cwd_facet_reports_current_directory() {
    let stdout = snapshot_self("--cwd");
    let cwd = rows(&stdout, "CWD");
    assert_eq!(cwd.len(), 1, "{stdout}");
    assert_eq!(cwd[0][1], std::process::id().to_string());
    let path: String = serde_json::from_str(&cwd[0][2]).expect("JSON-encoded cwd");
    assert_eq!(
        path,
        std::env::current_dir()
            .expect("current dir")
            .to_string_lossy()
    );
}

#[test]
fn status_facet_reports_state_nice_and_threads() {
    let stdout = snapshot_self("--status");
    let status = rows(&stdout, "STAT");
    assert_eq!(status.len(), 1, "{stdout}");
    assert_eq!(status[0][1], std::process::id().to_string());
    assert_eq!(
        status[0][2].chars().count(),
        1,
        "state must be one character"
    );
    status[0][3].parse::<i32>().expect("nice value");
    if status[0][4] != "-" {
        assert!(status[0][4].parse::<u32>().expect("thread count") > 0);
    }
}

#[test]
fn argv_facet_reports_full_argument_vector() {
    let stdout = snapshot_self("--argv");
    let argv = rows(&stdout, "ARGV");
    assert_eq!(argv.len(), 1, "{stdout}");
    assert_eq!(argv[0][1], std::process::id().to_string());
    let values: Vec<String> = serde_json::from_str(&argv[0][2]).expect("JSON-encoded argv");
    assert!(
        values.iter().any(|value| value.contains("v2_contract")),
        "harness argv missing: {values:?}"
    );
}

#[test]
fn missing_pid_reports_each_detail_facet_as_unreadable() {
    let pid = u32::MAX.to_string();
    let out = osfacts()
        .args([
            "snapshot", "--pids", &pid, "--uid", "--cwd", "--status", "--argv",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let stdout = String::from_utf8(out).expect("utf8");
    let facets: std::collections::HashSet<_> = rows(&stdout, "U")
        .into_iter()
        .map(|row| row[2].clone())
        .collect();
    assert_eq!(
        facets,
        ["uid", "cwd", "status", "argv"].map(String::from).into()
    );
}

#[test]
fn mem_and_start_time_are_independent_pid_facets() {
    let pid = std::process::id();
    let out = osfacts()
        .args([
            "snapshot",
            "--pids",
            &pid.to_string(),
            "--mem",
            "--start-time",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let stdout = String::from_utf8(out).expect("utf8");
    assert!(stdout.starts_with("V\t2\n"), "{stdout}");

    let memory = rows(&stdout, "M");
    assert_eq!(memory.len(), 1, "{stdout}");
    assert_eq!(memory[0][1], pid.to_string());
    assert!(memory[0][2].parse::<u64>().expect("rss bytes") > 0);

    let starts = rows(&stdout, "S");
    assert_eq!(starts.len(), 1, "{stdout}");
    assert_eq!(starts[0][1], pid.to_string());
    let start_us = starts[0][2].parse::<u64>().expect("epoch microseconds");
    let now_us = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .expect("clock after epoch")
        .as_micros() as u64;
    assert!(start_us > 1_000_000_000_000_000, "{start_us}");
    assert!(start_us <= now_us, "start={start_us}, now={now_us}");
}

#[test]
fn busy_process_cpu_time_increases_between_snapshots() {
    let busy = Listener::spawn_busy();
    let read = || {
        let out = osfacts()
            .args(["snapshot", "--pids", &busy.pid.to_string(), "--cpu-time"])
            .assert()
            .success()
            .get_output()
            .stdout
            .clone();
        let stdout = String::from_utf8(out).expect("utf8");
        let cpu = rows(&stdout, "C");
        assert_eq!(cpu.len(), 1, "{stdout}");
        assert_eq!(cpu[0][1], busy.pid.to_string());
        cpu[0][2].parse::<u64>().expect("cumulative cpu us")
    };

    let first = read();
    thread::sleep(Duration::from_millis(50));
    let second = read();
    assert!(
        second > first,
        "cpu time did not increase: first={first}, second={second}"
    );
}

#[test]
fn narrow_scope_emits_unclaimed_host_listener() {
    let claimed = Listener::spawn("127.0.0.1");
    let outside = Listener::spawn("127.0.0.1");
    let out = osfacts()
        .args(["snapshot", "--pids", &claimed.pid.to_string(), "--ports"])
        .output()
        .expect("run osfacts");
    let stdout = String::from_utf8(out.stdout).expect("utf8");
    let listeners = rows(&stdout, "L");
    let errors = rows(&stdout, "E");
    let claimed_row = listeners
        .iter()
        .find(|row| row.get(4) == Some(&claimed.port.to_string()))
        .unwrap_or_else(|| panic!("claimed fixture missing:\n{stdout}"));
    assert_eq!(claimed_row[1], "claimed");
    assert_eq!(claimed_row[2], claimed.pid.to_string());

    // Two `E` rows are benign for a `--ports` ask: darwin's unconditional
    // `ports_uid` (no darwin listener source carries an owning uid) and the
    // macOS 27 `ports_unclaimed` gate. Neither costs a claimed listener.
    assert!(
        errors
            .iter()
            .all(|row| matches!(row[2].as_str(), "ports_unclaimed" | "ports_uid")),
        "unexpected source errors: {errors:?}"
    );
    let pcblist_gated = errors
        .iter()
        .any(|row| row[1] == "darwin_tcp_pcblist" && row[2] == "ports_unclaimed");
    if pcblist_gated {
        assert!(
            out.status.success(),
            "claimed facts plus source blindness are a partial success: {stdout}"
        );
        assert!(
            listeners
                .iter()
                .all(|row| row.get(4) != Some(&outside.port.to_string())),
            "a gated host table cannot invent the out-of-scope listener: {stdout}"
        );
        return;
    }
    assert!(out.status.success(), "osfacts failed: {stdout}");

    let outside_row = listeners
        .iter()
        .find(|row| row.get(4) == Some(&outside.port.to_string()))
        .unwrap_or_else(|| panic!("out-of-scope fixture missing:\n{stdout}"));
    assert_eq!(outside_row[1], "unclaimed");
    assert_eq!(outside_row[2], "-");
    #[cfg(target_os = "linux")]
    assert_eq!(outside_row[3], unsafe { libc::geteuid() }.to_string());
}

#[test]
fn host_emits_cumulative_machine_facts() {
    let out = osfacts()
        .args(["host", "--load", "--mem", "--cpu", "--net", "--disk"])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let stdout = String::from_utf8(out).expect("utf8");
    assert!(stdout.starts_with("V\t2\n"), "{stdout}");
    for tag in ["HLOAD", "HMEM", "HSWAP", "HUP", "HCPU", "HNET", "HDISK"] {
        assert!(!rows(&stdout, tag).is_empty(), "missing {tag}:\n{stdout}");
    }

    let mem = &rows(&stdout, "HMEM")[0];
    let total = mem[1].parse::<u64>().expect("total memory");
    let available = mem[2].parse::<u64>().expect("available memory");
    assert!(total > 0 && available <= total, "{mem:?}");

    let disk = &rows(&stdout, "HDISK")[0];
    let total = disk[2].parse::<u64>().expect("total disk");
    let available = disk[3].parse::<u64>().expect("available disk");
    assert_eq!(disk[1], "/");
    assert!(total > 0 && available <= total, "{disk:?}");
}

#[test]
fn host_cpu_rows_include_model_and_nullable_mhz() {
    let out = osfacts()
        .args(["host", "--cpu"])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let stdout = String::from_utf8(out).expect("utf8");
    let cpus = rows(&stdout, "HCPU");
    assert!(!cpus.is_empty(), "{stdout}");
    for cpu in cpus {
        assert_eq!(cpu.len(), 8, "{cpu:?}");
        let model: String = serde_json::from_str(&cpu[6]).expect("JSON-encoded CPU model");
        assert!(!model.is_empty(), "CPU model must not be a sentinel");
        if cpu[7] != "-" {
            assert!(cpu[7].parse::<u64>().expect("frequency MHz") > 0);
        }
    }
}

#[test]
fn host_disk_distinguishes_free_from_available() {
    let out = osfacts()
        .args(["host", "--disk"])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let stdout = String::from_utf8(out).expect("utf8");
    let disk = rows(&stdout, "HDISK");
    assert_eq!(disk.len(), 1, "{stdout}");
    assert_eq!(disk[0].len(), 5, "{disk:?}");
    let total = disk[0][2].parse::<u64>().expect("total bytes");
    let available = disk[0][3].parse::<u64>().expect("available bytes");
    let free = disk[0][4].parse::<u64>().expect("free bytes");
    assert!(available <= free && free <= total, "{disk:?}");
}

//! Lane 1 — hermetic CLI-contract suite (gates every merge).
//!
//! Both platforms: self-referential bind-in-child (`osfacts-listener`) +
//! scoped snapshot. Assertions pin *our* fixtures — never "the host table is
//! empty". Host-wide state is never an oracle: OSF6 deliberately reports it.

mod common;

use common::{
    darwin_holder_walk_is_blind, darwin_pcblist_is_blind, hermetic_snapshot, hex_of_v4, hex_of_v6,
    l_addr_for_port, l_rows_for_port, only_benign_port_source_errors, osfacts, parse_holders_tsv,
    parse_tsv, redact_tsv, snapshot_pids, socket_holders, UnixHolder,
};
use std::net::{Ipv4Addr, Ipv6Addr};

// ── five bind fixtures ──────────────────────────────────────────────────

#[test]
fn fixture_loopback_v4() {
    let h = hermetic_snapshot("127.0.0.1");
    let (v, procs, ports, _, errors) = parse_tsv(&h.tsv);
    assert_eq!(v, 2);
    assert!(
        procs
            .iter()
            .any(|p| p.starts_with(&format!("P\t{}\t", h.listener_pid))),
        "helper pid must appear: {procs:?}"
    );
