/**
 * The capability the Effect actually buys, and the reason the spawn is an
 * `Effect.callback` around `execFile` rather than a Promise: a caller that
 * stops waiting KILLS the child.
 *
 * A Promise-shaped spawn had no way to say this. An abandoned
 * `snapshotHost(...)` left a real process running out its five-second deadline
 * against a host nobody was reading — invisible, and multiplied by every
 * abandoned probe.
 */
describe("an interrupted fiber kills the child it started", () => {
  it("leaves no process behind", async () => {
    await withStub(
      // `exec`, so the sleeping process IS the pid the stub reported — a
      // shell that forked would report a pid whose death proves nothing about
      // the sleep it left behind.
      (dir) =>
        `#!/bin/sh\necho $$ > ${join(dir, "child.pid")}\nexec sleep 30\n`,
      async (bin, dir) => {
        const pidFile = join(dir, "child.pid");
        const fiber = Effect.runFork(snapshotHost(bin, { procs: true }));
        let childPid = 0;
        await eventually(async () => {
          childPid = Number((await readFile(pidFile, "utf8")).trim());
          expect(childPid).toBeGreaterThan(0);
        });
        expect(alive(childPid)).toBe(true);

        await run(Fiber.interrupt(fiber));

        await eventually(() => {
          expect(alive(childPid)).toBe(false);
        });
      },
    );
  });
});

describe("a refused ask is never an empty answer", () => {
  /**
   * The binary writes its version line on the USAGE path too, so a document
   * shape alone cannot tell an answer from a refusal. An older binary that
   * does not have the verb the caller asked for exits 2 after that version
   * line — and reading it as a well-formed "nothing found" is how a supervisor
   * would conclude a live socket is free.
   */
  it("refuses a usage-error document (exit 2) rather than parsing it as nothing-found", async () => {
    await withStub(
      '#!/bin/sh\nprintf "V\\t2\\n"\necho "osfacts: unknown command \'socket-holders\'" >&2\nexit 2\n',
      async (bin) => {
        await expect(run(socketHolders(bin, "/run/a.sock"))).rejects.toThrow(
          /unknown command/,
        );
        await expect(run(snapshotHost(bin, { procs: true }))).rejects.toThrow(
          OsfactsSpawnError,
        );
      },
    );
  });
});

/**
 * The sync twin must obey the SAME exit-status rule as the async one.
 *
 * It nearly did not: `promisify(execFile)` reports the exit status on `.code`,
 * but `execFileSync` throws the raw spawnSync result, whose status is
 * `.status` and which carries no `.code` at all. A guard reading only `.code`
 * is therefore silently inert here — it discards the binary's documented
 * exit-1 document (losing the `E` rows that name which source went blind) and
 * would equally have failed to refuse an exit-2 usage document. These pins
 * exist so the twins cannot drift apart again.
 */
describe("the sync twin obeys the same exit-status rule", () => {
  it("keeps the E rows of a totally-blind probe that exited non-zero", async () => {
    await withStub(
      '#!/bin/sh\nprintf "V\\t2\\nE\\tproc_readdir\\tproc\\tEACCES\\n"\nexit 1\n',
      (bin) =>
        expect(snapshotPidsSync(bin, [1], { startTime: true })).toMatchObject({
          startTimes: [],
          errors: [{ source: "proc_readdir", facet: "proc", code: "EACCES" }],
        }),
    );
  });

  it("refuses a usage-error document (exit 2) rather than parsing it as nothing-found", async () => {
    await withStub(
      '#!/bin/sh\nprintf "V\\t2\\n"\necho "osfacts: unknown command" >&2\nexit 2\n',
      (bin) =>
        expect(() => snapshotPidsSync(bin, [1], { startTime: true })).toThrow(
          /unknown command/,
        ),
    );
  });

  it("names the exit status when the failure is not a spawn errno", async () => {
    await withStub("#!/bin/sh\nexit 2\n", (bin) =>
      expect(() => snapshotPidsSync(bin, [1], { startTime: true })).toThrow(
        /exit 2/,
      ),
    );
  });

  it("still fails loudly when a non-zero exit produced no document", async () => {
    await withStub("#!/bin/sh\necho boom >&2\nexit 3\n", (bin) =>
      expect(() => snapshotPidsSync(bin, [1], { startTime: true })).toThrow(
        OsfactsSpawnError,
      ),
    );
  });
});

/** A wire-faithful `socket-holders` document, one field at a time. */
function reading(over: Partial<SocketHoldersReading>): SocketHoldersReading {
  return { holders: [], procs: [], unreadable: [], errors: [], ...over };
}

describe("foldSocketOccupancy — three answers, never one", () => {
  it("names every claimed holder, with its command", () => {
    expect(
      foldSocketOccupancy(
        reading({
          holders: [
            { status: "claimed", pid: 4242 },
            { status: "claimed", pid: 4243 },
          ],
          procs: [{ pid: 4242, ppid: 1, name: "kaval" }],
        }),
      ),
    ).toEqual({
      kind: "held",
      holders: [
        { pid: 4242, command: "kaval" },
        // Named by the OS, but its identity read lost the race — still a
        // holder, and still a kill candidate the handshake may confirm. The
        // name is ABSENT, not `"?"`: a sentinel inside the value would be
        // indistinguishable from a process whose name really is `?`.
        { pid: 4243, command: undefined },
      ],
    });
  });

  it("reports a proven-empty document as `none`, the ONLY proof of freedom", () => {
    expect(foldSocketOccupancy(reading({}))).toEqual({ kind: "none" });
  });

  /** The linux shape: the socket IS bound, and no pid we may inspect holds it. */
  it("keeps a bound-but-unnameable holder out of `none`", () => {
    const folded = foldSocketOccupancy(
      reading({ holders: [{ status: "unclaimed" }] }),
    );

    expect(folded.kind).toBe("unattributed");
    expect(folded).not.toEqual({ kind: "none" });
  });

  /** The darwin shape: the search itself could not complete. */
  it("keeps a blind search out of `none`", () => {
    const folded = foldSocketOccupancy(
      reading({
        errors: [
          {
            source: "darwin_proc_fds",
            facet: "socket_holders",
            code: "BLIND_OR_EMPTY",
          },
        ],
      }),
    );

    expect(folded.kind).toBe("unattributed");
    expect(folded).toMatchObject({
      detail: expect.stringContaining("darwin_proc_fds"),
    });
  });

  /** A named holder is an answer even when its NAME could not be read. That
   *  loss is the shape the verb really emits — a per-pid `U` row, not an
   *  `E … proc …` source error (which `SOCKET_HOLDERS_SOURCE_FACETS` no
   *  longer promises, because no reader can write one). */
  it("still names holders when the identity read lost one pid", () => {
    expect(
      foldSocketOccupancy(
        reading({
          holders: [{ status: "claimed", pid: 7 }],
          unreadable: [{ pid: 7, facet: "proc", errno: "EACCES" }],
        }),
      ),
    ).toEqual({ kind: "held", holders: [{ pid: 7, command: undefined }] });
  });

  /** An unclaimed row beside a claimed one does not weaken the claim: the
   *  recovery has a pid to handshake, which is what it needs. */
  it("prefers a named holder over an unattributed sibling row", () => {
    expect(
      foldSocketOccupancy(
        reading({
          holders: [{ status: "unclaimed" }, { status: "claimed", pid: 9 }],
          procs: [{ pid: 9, ppid: 1, name: "kaval" }],
        }),
      ),
    ).toEqual({ kind: "held", holders: [{ pid: 9, command: "kaval" }] });
  });
});

describe("foldSocketOccupancy refuses a contradictory document", () => {
  /**
   * `none` is the most dangerous answer this fold can give, so it is given
   * only for a document that says nothing at all. A `P` or `U` row names the
   * identity of a holder — both exist only for a pid an `H` row already
   * claimed — so a document carrying one while carrying neither an `H` row nor
   * a blind source is a contradiction, and reading it as an unheld socket
   * would assert absence out of a shape the binary cannot emit.
   */
  it("throws rather than folding a holder-identity-without-a-holder to `none`", () => {
    for (const body of [
      "V\t2\nP\t7\t1\tkaval\n",
      "V\t2\nU\t7\tproc\tEACCES\n",
    ]) {
      const reading = parseSocketHoldersOutput(body);
      expect(() => foldSocketOccupancy(reading)).toThrow(OsfactsParseError);
    }
  });

  it("still folds a genuinely empty document to `none`", () => {
    expect(foldSocketOccupancy(parseSocketHoldersOutput("V\t2\n"))).toEqual({
      kind: "none",
    });
  });
});

//! Shared hermetic-test helpers.
//!
//! Both platforms use the same strategy: bind port 0 in a parked
//! `osfacts-listener` child, snapshot that child's subtree (or exact pid),
//! assert *our* fixture appears exactly when the kernel exposes its listener
//! table. A Darwin sandbox may instead report that source as explicitly blind;
//! the process fact must still survive. Pid and port are redacted for insta;
//! nothing claims the host port table is empty. There is no
//! `unshare` / netns path — hermeticity is scoped assertions, not an
//! isolated network namespace.

use assert_cmd::Command;
use std::ffi::OsStr;
use std::io::{BufRead, BufReader};
use std::path::{Path, PathBuf};
use std::process::{Child, Command as StdCommand, Stdio};
use tempfile::{tempdir, TempDir};

/// A parked `osfacts-listener` child, and the ONE line it announced.
///
/// Both fixtures below stand on this: the binary lookup, the piped stdio, and
/// the handshake are one shape, because they are one fact — the child prints
/// exactly one line once it is ready, so a test never races the bind. Each
/// fixture then interprets only its OWN announce line: a port on one, the word
/// `bound` on the other.
struct Announced {
    child: Child,
    pid: u32,
    line: String,
}

fn spawn_listener<I, S>(args: I) -> Announced
where
    I: IntoIterator<Item = S>,
    S: AsRef<OsStr>,
{
    let bin = env!("CARGO_BIN_EXE_osfacts-listener");
    let mut child = StdCommand::new(bin)
        .args(args)
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .unwrap_or_else(|e| panic!("spawn osfacts-listener: {e}"));
    let pid = child.id();
    let stdout = child.stdout.take().expect("listener stdout");
    let mut line = String::new();
    BufReader::new(stdout)
        .read_line(&mut line)
        .expect("read listener announce line");
    Announced { child, pid, line }
}

/// Kill a fixture's child and WAIT for it, so the resource it held (a port, a
/// bound socket) is genuinely released before the test asks about it again.
fn reap(child: &mut Child) {
    let _ = child.kill();
    let _ = child.wait();
}

/// Result of a hermetic bind+snapshot.
pub struct Hermetic {
    pub listener_pid: u32,
    pub port: u16,
    pub tsv: String,
}

/// Bind `bind` in a parked helper child and snapshot its process subtree.
pub fn hermetic_snapshot(bind: &str) -> Hermetic {
    let listener = Listener::spawn(bind);
    let tsv = snapshot_roots(listener.pid);
    Hermetic {
        listener_pid: listener.pid,
        port: listener.port,
        tsv,
    }
}

/// Like [`hermetic_snapshot`] but `--pids` instead of `--roots`.
#[allow(dead_code)] // kept for parity with --pids call sites / future fixtures
pub fn hermetic_snapshot_pids(bind: &str) -> Hermetic {
    let listener = Listener::spawn(bind);
    let tsv = snapshot_pids(listener.pid);
    Hermetic {
        listener_pid: listener.pid,
        port: listener.port,
        tsv,
    }
}

/// A spawned listener helper: bind port 0, print the kernel-chosen port, park.
pub struct Listener {
    child: Child,
    pub pid: u32,
    pub port: u16,
}

impl Listener {
    pub fn spawn(bind: &str) -> Self {
        Self::spawn_with_args(bind, &[])
    }

    pub fn spawn_busy() -> Self {
        Self::spawn_with_args("127.0.0.1", &["--spin"])
    }

    fn spawn_with_args(bind: &str, extra: &[&str]) -> Self {
        let announced = spawn_listener([&[bind], extra].concat());
        // This fixture's announce line is the kernel-chosen port.
        let port: u16 =
            announced.line.trim().parse().unwrap_or_else(|_| {
                panic!("listener did not print a port; got {:?}", announced.line)
            });
        Self {
            child: announced.child,
            pid: announced.pid,
            port,
        }
    }
}

impl Drop for Listener {
    fn drop(&mut self) {
        reap(&mut self.child);
    }
}

/// A spawned helper holding a bound UNIX socket at a path this test owns.
///
/// The path lives in a `TempDir` the fixture keeps alive, so nothing outside
/// this test can hold it and no assertion depends on host inventory.
pub struct UnixHolder {
    child: Child,
    pub pid: u32,
    _dir: TempDir,
    pub path: PathBuf,
}

impl UnixHolder {
    /// Bind `name` inside a fresh temp dir and wait for the child to say so.
    pub fn spawn(name: &str) -> Self {
        let dir = tempdir().expect("temp dir");
        let path = dir.path().join(name);
        let announced = spawn_listener([OsStr::new("--unix"), path.as_os_str()]);
        // This fixture's announce line is the bind confirmation.
        assert_eq!(
            announced.line.trim(),
            "bound",
            "listener did not confirm the unix bind"
        );
        Self {
            child: announced.child,
            pid: announced.pid,
            _dir: dir,
            path,
        }
    }

    /// Kill the holder and wait for it to be reaped, so the socket is
    /// genuinely unbound before the caller asks about the path again. The
    /// FILE survives — that is the point of the stale-socket fixture.
    pub fn kill(&mut self) {
        reap(&mut self.child);
    }
}

impl Drop for UnixHolder {
    fn drop(&mut self) {
        self.kill();
    }
}

/// `osfacts socket-holders <path> [--procs]` — stdout and exit status, both.
/// The status is part of the contract (a document with no facts and a blind
/// source exits 1), so no helper may `assert().success()` it away.
pub fn socket_holders(path: &Path, procs: bool) -> (String, bool) {
    let mut cmd = osfacts();
    cmd.arg("socket-holders").arg(path);
    if procs {
        cmd.arg("--procs");
    }
    let out = cmd.output().expect("run osfacts socket-holders");
    (
        String::from_utf8(out.stdout).expect("utf8"),
        out.status.success(),
    )
}

/// The rows of a `socket-holders` document, by tag.
pub struct HolderRows {
    pub holders: Vec<String>,
    pub procs: Vec<String>,
    pub unreadable: Vec<String>,
    pub errors: Vec<String>,
}

/// The version line, then every row bucketed by its tag in the order `tags`
/// names them. One loop for every document shape, so the two parsers below
/// cannot drift on what a version line is or on what an unexpected tag does.
/// A tag not in `tags` panics: a document row no test classified is a contract
/// change, not something to silently drop.
fn split_tsv<const N: usize>(stdout: &str, tags: [&str; N]) -> (u32, [Vec<String>; N]) {
    let mut lines = stdout.lines();
    let first = lines.next().expect("stdout must have a version line");
    let version = first
        .strip_prefix("V\t")
        .expect("first line must be V\\tN")
        .parse::<u32>()
        .expect("version number");
    let mut out: [Vec<String>; N] = std::array::from_fn(|_| Vec::new());
    for line in lines {
        if line.is_empty() {
            continue;
        }
        let tag = line.split('\t').next().unwrap_or_default();
        let slot = tags
            .iter()
            .position(|want| *want == tag)
            .unwrap_or_else(|| panic!("unexpected row tag {tag:?} in {line}"));
        out[slot].push(line.to_string());
    }
    (version, out)
}

pub fn parse_holders_tsv(stdout: &str) -> HolderRows {
    let (version, [holders, procs, unreadable, errors]) = split_tsv(stdout, ["H", "P", "U", "E"]);
    assert_eq!(version, 2, "socket-holders must carry the schema version");
    HolderRows {
        holders,
        procs,
        unreadable,
        errors,
    }
}

/// Darwin has no world-readable table of bound unix sockets, so a walk that
/// claimed nobody may simply have been denied another user's descriptors. A
/// linux run never carries this row; a darwin run carries it exactly when it
/// named no holder.
pub fn darwin_holder_walk_is_blind(errors: &[String]) -> bool {
    errors
        .iter()
        .any(|row| row == "E\tdarwin_proc_fds\tsocket_holders\tBLIND_OR_EMPTY")
}

pub fn osfacts() -> Command {
    Command::cargo_bin("osfacts").expect("osfacts binary")
}

